on:
  push:
    tags:
      - "v*.*.*"
  # A release that was published by hand still needs its offline image. Without
  # this the only way to attach one is to delete and re-push the tag.
  workflow_dispatch:
    inputs:
      tag:
        description: "Existing release tag to build the offline image for"
        required: true

permissions:
  contents: write

jobs:
  release:
    runs-on: ubuntu-latest
    services:
      postgres:
        image: postgres:17-alpine
        env:
          POSTGRES_USER: resso
          POSTGRES_PASSWORD: integration-password
          POSTGRES_DB: resso
        ports:
          - 5432:5432
        options: >-
          --health-cmd "pg_isready -U resso -d resso"
          --health-interval 5s
          --health-timeout 5s
          --health-retries 12
    steps:
      - uses: actions/checkout@v7
        with:
          fetch-depth: 0
          ref: ${{ inputs.tag || github.ref }}
      - name: Validate tag
        shell: bash
        run: |
          tag="${{ inputs.tag || github.ref_name }}"
          [[ "$tag" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]]
          # Everything below names the release through this one variable, so a
          # dispatched run builds the tag it was given and not whatever branch
          # the workflow file was read from.
          echo "RELEASE_TAG=$tag" >> "$GITHUB_ENV"
          echo "RELEASE_COMMIT=$(git rev-parse HEAD)" >> "$GITHUB_ENV"
      - name: Set up Go
        uses: actions/setup-go@v7
        with:
          go-version-file: go.mod
          cache: true
      - name: Test backend
        env:
          RESSO_TEST_POSTGRES_DSN: postgres://resso:integration-password@127.0.0.1:5432/resso?sslmode=disable
        run: go test ./... && go vet ./...
      - uses: actions/setup-node@v7
        with:
          node-version: 22.23.0
          cache: npm
          cache-dependency-path: web/package-lock.json
      - name: Test frontend
        working-directory: web
        run: npm ci && npm run test && npm run build
      - name: Build offline image
        shell: bash
        run: |
          docker build --platform linux/amd64 \
            --build-arg "VERSION=${RELEASE_TAG}" \
            --build-arg "COMMIT=${RELEASE_COMMIT}" \
            --build-arg "BUILD_TIME=$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
            --tag "resso:${RELEASE_TAG}" .
          docker image inspect "resso:${RELEASE_TAG}" >/dev/null
          test "$(docker image inspect --format '{{.Os}}/{{.Architecture}}' "resso:${RELEASE_TAG}")" = "linux/amd64"
      - name: Test built offline image
        shell: bash
        env:
          POSTGRES_DSN: postgres://resso:integration-password@127.0.0.1:5432/resso?sslmode=disable
          BOOTSTRAP_ADMIN: admin
          BOOTSTRAP_ADMIN_PASSWORD: integration-password-123
          ENCRYPTION_KEY: MDEyMzQ1Njc4OTAxMjM0NTY3ODkwMTIzNDU2Nzg5MDE=
        run: |
          container_name=resso-release-smoke
          cleanup() {
            status=$?
            if [ "$status" -ne 0 ]; then
              docker logs "$container_name" 2>/dev/null || true
            fi
